import{validateReport,departure,demoReport,contributorEvidenceSlices,signalNames}from'./model.js';
const $=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),pct=x=>(x*100).toFixed(1)+'%',badge=r=>`<span class="badge ${r}">${r}</span>`;
let report=null,selected=null,activePerson=null;
const contributorTotals=r=>{const m=new Map;for(const c of r.components)for(const p of c.contributors){const v=m.get(p.contributor)||{name:p.name,score:0};v.score+=p.score;m.set(p.contributor,v)}return[...m.entries()].sort((a,b)=>b[1].score-a[1].score)};
function setScreen(screen){$('local-landing').hidden=screen!=='local';$('hosted-landing').hidden=screen!=='hosted';$('dashboard').hidden=screen!=='dashboard';$('another').hidden=screen!=='dashboard';}
function load(data,name,type){report=validateReport(data);selected=report.components[0]?.component;activePerson=null;const source=type==='LOCAL REPOSITORY'?name.replace(/[\\/]+$/,'').split(/[\\/]/).pop()||'Local repository':name;$('source-name').textContent=source;$('source-type').textContent=type;setScreen('dashboard');render();}
function render(){const people=contributorTotals(report),metrics=[['Components',report.components.length],['Contributors',people.length],['Critical continuity risk',report.components.filter(c=>c.risk==='CRITICAL').length],['Commits',report.commit_count]];$('revision').textContent='REV '+report.revision.slice(0,12);$('reference').textContent=new Date(report.as_of).toLocaleDateString('en-US');$('metrics').innerHTML=metrics.map(([x,y])=>`<article class="metric"><div class="label">${x}</div><div class="value">${y}</div></article>`).join('');$('person').innerHTML=people.map(([id,p])=>`<option value="${esc(id)}">${esc(p.name)}</option>`).join('');renderOverview();renderComponents();renderContributors();renderEvidence();renderStress();}
function renderOverview(){const risks=['LOW','MEDIUM','HIGH','CRITICAL'],slices=contributorEvidenceSlices(report),gradient=slices.reduce((a,s,i)=>{const start=slices.slice(0,i).reduce((n,x)=>n+x.share*100,0),end=start+s.share*100;return a+`#${['295ecc','65a4ce','e4b85d','8b83bc','66a89a','94a3b8'][i]} ${start}% ${end}%,`},'').slice(0,-1),top=[...report.components].sort((a,b)=>b.concentration-a.concentration).slice(0,5);$('overview-content').innerHTML=`<article class="panel summary"><h2>Continuity Risk Distribution</h2><div class="risk-grid">${risks.map(r=>`<div><span>${r}</span><strong>${report.components.filter(c=>c.risk===r).length}</strong></div>`).join('')}</div></article><article class="panel summary"><h2>Contributor Evidence Concentration</h2><p class="muted">Historical evidence share across the analyzed repository.</p><div class="donut-row"><div class="donut" style="background:conic-gradient(${gradient})" aria-label="Contributor evidence concentration"></div><ul class="legend">${slices.map((s,i)=>`<li><span class="dot d${i}"></span>${esc(s.name)} <strong>${pct(s.share)}</strong></li>`).join('')}</ul></div><p class="muted">Evidence share reflects historical repository activity under the experimental model. It does not measure employee importance, performance, expertise, or replaceability.</p></article><article class="panel summary wide"><h2>Highest Concentration Components</h2>${top.map(c=>`<button class="top-component" data-component="${esc(c.component)}">${esc(c.component)} ${badge(c.risk)} <strong>${c.concentration.toFixed(2)}</strong></button>`).join('')}</article>`;}
function renderComponents(){const q=$('search').value.toLowerCase(),risk=$('risk').value,cs=report.components.filter(c=>(!risk||c.risk===risk)&&c.component.toLowerCase().includes(q)).sort((a,b)=>b.concentration-a.concentration||a.component.localeCompare(b.component));if(!cs.some(c=>c.component===selected)){selected=cs[0]?.component;activePerson=null;}$('visible-count').textContent=cs.length+'/'+report.components.length;$('empty').hidden=!!cs.length;$('component-rows').innerHTML=cs.map(c=>`<tr class="${selected===c.component?'selected':''}"><td><button class="component-link" data-component="${esc(c.component)}" aria-pressed="${selected===c.component}">${esc(c.component)}</button></td><td>${badge(c.risk)}</td><td>${c.concentration.toFixed(3)}</td><td>${c.contributors.length}</td></tr>`).join('');renderDetail();}
function renderDetail(){const component=report.components.find(c=>c.component===selected);if(!component){$('detail').innerHTML='<h2>Component selection</h2><p class="muted">There are no components to display in this view.</p>';return;}const people=[...component.contributors].sort((a,b)=>b.share-a.share),person=people.find(p=>p.contributor===activePerson)||people[0];activePerson=person.contributor;$('detail').innerHTML=`<div class="detail-top"><p class="eyebrow">COMPONENT DETAIL</p>${badge(component.risk)}</div><h2>${esc(component.component)}</h2><p class="muted">${people.length} contributors · ${new Set(people.flatMap(p=>p.files)).size} historical files</p><h3>Contribution shares</h3>${people.map(p=>`<div class="contributor"><button data-contributor="${esc(p.contributor)}">${esc(p.name)}<small>${esc(p.contributor)}</small></button><strong>${pct(p.share)}</strong></div>`).join('')}<div class="signals"><h3>${esc(person.name)} · score evidence</h3><p class="muted">Raw score ${person.score.toFixed(3)} · ${person.commits} commits · ${person.files.length} files</p>${Object.entries(signalNames).map(([key,name])=>`<div class="signal"><span>${name}</span><div class="bar"><span style="width:${person.signals[key]*100}%"></span></div><span>${person.signals[key].toFixed(2)}</span></div>`).join('')}</div><details class="evidence"><summary>File evidence (${person.files.length})</summary><ul>${person.files.map(file=>`<li>${esc(file)}</li>`).join('')}</ul></details>`;}
function renderContributors(){const contributors=new Map();for(const component of report.components)for(const person of component.contributors){const current=contributors.get(person.contributor)||{...person,components:new Set(),files:new Set(),score:0};current.components.add(component.component);person.files.forEach(file=>current.files.add(file));current.score+=person.score;contributors.set(person.contributor,current);}$('contributor-rows').innerHTML=[...contributors.values()].sort((a,b)=>b.components.size-a.components.size||a.name.localeCompare(b.name)).map(person=>`<tr><td><strong>${esc(person.name)}</strong><small>${esc(person.contributor)}</small></td><td>${person.components.size}</td><td>${person.files.size}</td><td>${person.score.toFixed(3)}</td></tr>`).join('');}
function renderEvidence(){$('evidence-rows').innerHTML=report.components.map(c=>`<tr><td>${esc(c.component)}</td><td>${badge(c.risk)}</td><td>${c.contributors.length}</td><td>${new Set(c.contributors.flatMap(p=>p.files)).size}</td><td>${c.concentration.toFixed(3)}</td></tr>`).join('');}
function renderStress(){const xs=departure(report,$('person').value);$('impact-summary').textContent=xs.length?`${xs.length} affected components`:'';$('impact-rows').innerHTML=xs.map(i=>`<tr><td>${esc(i.component)}</td><td>${pct(i.loss)}</td><td>${i.successor?esc(i.successor.name):'No evidence overlap'}</td><td>${i.successor?pct(i.successor.overlap):'—'}</td><td>${i.uncovered.length} coverage gaps</td></tr>`).join('');}
function setView(v){for(const n of ['overview','components','contributors','evidence','stress']){$(n).hidden=n!==v;$(n+'-tab').classList.toggle('active',n===v);}}
for(const n of ['overview','components','contributors','evidence','stress'])$(n+'-tab').onclick=()=>setView(n);$('search').oninput=renderComponents;$('risk').onchange=renderComponents;$('person').onchange=renderStress;$('component-rows').onclick=e=>{const b=e.target.closest('[data-component]');if(b){selected=b.dataset.component;activePerson=null;renderComponents();}};$('detail').onclick=e=>{const b=e.target.closest('[data-contributor]');if(b){activePerson=b.dataset.contributor;renderDetail();}};$('overview-content').onclick=e=>{const b=e.target.closest('[data-component]');if(b){selected=b.dataset.component;activePerson=null;setView('components');renderComponents();}};
async function analyze(input,button,type){const source=$(input).value.trim();if(!source){$('message').textContent='Enter a repository source.';return}const b=$(button);b.disabled=true;b.textContent=type==='REMOTE GIT'?'Cloning repository…':'Reading Git history…';try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({repository:source})}),data=await response.json();if(!response.ok)throw Error(data.error||'Analysis failed.');b.textContent='Preparing dashboard…';load(data,source,type)}catch(e){$('message').textContent=e.message}finally{b.disabled=false;b.textContent=type==='REMOTE GIT'?'Clone & Analyze':'Analyze Repository'}}
$('run-local-analysis').onclick=()=>analyze('repository-path','run-local-analysis','LOCAL REPOSITORY');$('run-clone-analysis').onclick=()=>analyze('clone-url','run-clone-analysis','PUBLIC GIT REPOSITORY');$('another').onclick=()=>{report=null;$('message').textContent='';setScreen('local')};$('explore-demo').onclick=()=>load(demoReport(),'Synthetic continuity demo','PUBLIC DEMO');
async function boot(){if(['127.0.0.1','localhost','::1'].includes(location.hostname)){try{if(!(await fetch('/api/health')).ok)throw Error();const r=await fetch('/api/report');if(r.ok)load(await r.json(),'Repository analysis','LOCAL EXPLORER');else setScreen('local');return}catch{}}setScreen('hosted')}boot();
